package school.magiccodex.party;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.io.*;import java.net.*;import java.util.concurrent.*;import com.velocitypowered.api.proxy.*;import com.velocitypowered.api.proxy.server.ServerInfo;import com.velocitypowered.api.proxy.messages.MinecraftChannelIdentifier;import com.velocitypowered.api.event.connection.PluginMessageEvent;import com.velocitypowered.api.event.proxy.ProxyShutdownEvent;import org.slf4j.LoggerFactory;import static org.junit.jupiter.api.Assertions.*;
class PartyDiscoveryIntegrationTest {
 @TempDir Path dir;PartyPlugin plugin;UUID actor=UUID.randomUUID(),friend=UUID.randomUUID();Player player;ServerConnection connection;List<byte[]> replies=new ArrayList<>();
 @BeforeEach void setup()throws Exception{var proxy=NetworkChatIntegrationTest.mock(ProxyServer.class,(m,a)->null);plugin=new PartyPlugin(proxy,LoggerFactory.getLogger(getClass()),dir);NetworkChatIntegrationTest.field("ready").set(plugin,true);NetworkChatIntegrationTest.field("membershipChangedAt").set(plugin,0L);((Set<String>)NetworkChatIntegrationTest.field("trusted").get(plugin)).add("school");var book=new PartyBook(8);book.restore(new PartyBook.Party(UUID.randomUUID(),actor,List.of(actor,friend)));NetworkChatIntegrationTest.field("book").set(plugin,book);player=NetworkChatIntegrationTest.mock(Player.class,(m,a)->switch(m){case "getUniqueId"->actor;case "getCurrentServer"->Optional.ofNullable(connection);default->null;});connection=backend("school");}
 ServerConnection backend(String name){return NetworkChatIntegrationTest.mock(ServerConnection.class,(m,a)->switch(m){case "getServerInfo"->new ServerInfo(name,new InetSocketAddress("localhost",25566));case "getPlayer"->player;case "sendPluginMessage"->{replies.add((byte[])a[1]);yield true;}default->null;});}
 byte[] request()throws Exception{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeByte(1);out.writeLong(17);out.writeLong(23);out.writeLong(System.currentTimeMillis()-10);return bytes.toByteArray();}
 PluginMessageEvent event(Object source,byte[] data){return new PluginMessageEvent((com.velocitypowered.api.proxy.messages.ChannelMessageSource)source,player,MinecraftChannelIdentifier.from("chacademi:party_discovery"),data);}
 void drain()throws Exception{((ExecutorService)NetworkChatIntegrationTest.field("worker").get(plugin)).submit(()->{}).get(3,TimeUnit.SECONDS);}
 @AfterEach void close(){plugin.shutdown(new ProxyShutdownEvent());}
 @Test void trustedResponseEchoesNonceAndAuthoritativeMembership()throws Exception{plugin.discoveryParty(event(connection,request()));drain();assertEquals(1,replies.size());var input=new DataInputStream(new ByteArrayInputStream(replies.getFirst()));assertEquals(1,input.readByte());assertEquals(17,input.readLong());assertEquals(23,input.readLong());assertEquals(2,input.readUnsignedByte());var ids=Set.of(new UUID(input.readLong(),input.readLong()),new UUID(input.readLong(),input.readLong()));assertEquals(Set.of(actor,friend),ids);assertEquals(0,input.available());}
 @Test void clientAndStaleAndUntrustedPacketsNeverGetMembership()throws Exception{var forged=event(player,request());plugin.discoveryParty(forged);assertEquals(PluginMessageEvent.ForwardResult.handled(),forged.getResult());var stale=connection;connection=backend("school");plugin.discoveryParty(event(stale,request()));connection=backend("other");plugin.discoveryParty(event(connection,request()));drain();assertTrue(replies.isEmpty());}
 @Test void partyChangeAfterSplashRejectsEvenIfCurrentPartyMatches()throws Exception{NetworkChatIntegrationTest.field("membershipChangedAt").set(plugin,System.currentTimeMillis());plugin.discoveryParty(event(connection,request()));drain();assertEquals(1,replies.size());assertEquals(0,replies.getFirst()[17]);}
 @Test void malformedPayloadIsIgnored()throws Exception{plugin.discoveryParty(event(connection,new byte[18]));drain();assertTrue(replies.isEmpty());}
}
